from typing import List

class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)
        vals = sorted(set(nums))
        idx = {v: i + 1 for i, v in enumerate(vals)}

        class BIT:
            def __init__(self, size: int):
                self.n = size
                self.bit = [0] * (size + 1)

            def add(self, i: int, delta: int) -> None:
                while i <= self.n:
                    self.bit[i] += delta
                    i += i & -i

            def query(self, i: int) -> int:
                total = 0
                while i > 0:
                    total += self.bit[i]
                    i -= i & -i
                return total

            def kth(self, k: int) -> int:
                pos = 0
                step = 1 << (self.n.bit_length() - 1)
                while step:
                    nxt = pos + step
                    if nxt <= self.n and self.bit[nxt] < k:
                        pos = nxt
                        k -= self.bit[nxt]
                    step >>= 1
                return pos + 1

        count_bit = BIT(len(vals))
        sum_bit = BIT(len(vals))

        def add_value(v: int, delta: int) -> None:
            p = idx[v]
            count_bit.add(p, delta)
            sum_bit.add(p, delta * v)

        total_sum = 0
        for i in range(x):
            add_value(nums[i], 1)
            total_sum += nums[i]

        costs = []
        median_rank = (x + 1) // 2

        for start in range(n - x + 1):
            median_pos = count_bit.kth(median_rank)
            median = vals[median_pos - 1]

            left_count = count_bit.query(median_pos)
            left_sum = sum_bit.query(median_pos)
            right_count = x - left_count
            right_sum = total_sum - left_sum

            costs.append(
                median * left_count - left_sum +
                right_sum - median * right_count
            )

            if start + x < n:
                add_value(nums[start], -1)
                total_sum -= nums[start]
                add_value(nums[start + x], 1)
                total_sum += nums[start + x]

        m = len(costs)
        inf = 10**30
        prev = [0] * (m + 1)

        for _ in range(k):
            cur = [inf] * (m + 1)
            for i in range(1, m + 1):
                start = i - 1
                before = max(0, start - x + 1)
                cur[i] = min(cur[i - 1], prev[before] + costs[start])
            prev = cur

        return prev[m]
